package app.kinnect.live;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;

/** Host-only compact overlay. Room messages arrive from the existing authenticated socket. */
final class GameCommentOverlay {
 interface Actions{void mic();void pause();void room();void reply(String message);}
 private final Context context;private final WindowManager windows;private final Actions actions;private final ArrayDeque<String> comments=new ArrayDeque<>();private LinearLayout panel,body,tools;private LinearLayout composer;private EditText reply;private TextView viewerCount;private WindowManager.LayoutParams at;private boolean collapsed,muted,paused;private long lastReply;private int expandedWidth,viewers;
 GameCommentOverlay(Context context,Actions actions){this.context=context;this.actions=actions;windows=(WindowManager)context.getSystemService(Context.WINDOW_SERVICE);}
 private int dp(int n){return Math.round(n*context.getResources().getDisplayMetrics().density);}
 private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView text(String value,int size){TextView t=new KinnectText(context);t.setText(value);t.setTextColor(-1);t.setTextSize(size);return t;}
 private ImageView icon(String glyph,String label,Runnable run){ImageView v=new ImageView(context);android.graphics.drawable.Drawable d=WebIcons.load(context,glyph);d.setTint(-1);v.setImageDrawable(d);v.setPadding(dp(11),dp(11),dp(11),dp(11));v.setContentDescription(I18n.t(label));v.setOnClickListener(w->run.run());return v;}
 boolean show(){if(panel!=null)return true;if(!Settings.canDrawOverlays(context))return false;try{panel=new LinearLayout(context);panel.setOrientation(1);panel.setPadding(dp(4),dp(2),dp(4),dp(4));panel.setBackground(bg(0xb51b1429,16));LinearLayout header=new LinearLayout(context);header.setGravity(Gravity.CENTER_VERTICAL);TextView grip=text("LIVE",11);grip.setTypeface(null,1);grip.setGravity(Gravity.CENTER);grip.setContentDescription(I18n.t("Kéo để di chuyển bình luận"));header.addView(grip,new LinearLayout.LayoutParams(0,dp(40),1));LinearLayout watching=new LinearLayout(context);watching.setGravity(Gravity.CENTER_VERTICAL);ImageView eye=new ImageView(context);android.graphics.drawable.Drawable eyeArt=WebIcons.load(context,"eye");eyeArt.setTint(-1);eye.setImageDrawable(eyeArt);watching.addView(eye,new LinearLayout.LayoutParams(dp(15),dp(15)));viewerCount=text(String.valueOf(viewers),11);viewerCount.setPadding(dp(4),0,dp(4),0);watching.addView(viewerCount);header.addView(watching,new LinearLayout.LayoutParams(-2,dp(40)));header.addView(icon("message_square","Thu gọn / Mở bình luận",()->{closeReply();collapsed=!collapsed;render();}),new LinearLayout.LayoutParams(dp(40),dp(40)));panel.addView(header);body=new LinearLayout(context);body.setOrientation(1);body.setPadding(dp(6),0,dp(6),dp(3));panel.addView(body);tools=new LinearLayout(context);panel.addView(tools);composer=new LinearLayout(context);composer.setGravity(Gravity.CENTER_VERTICAL);composer.setVisibility(View.GONE);reply=new KinnectInput(context);reply.setTextColor(-1);reply.setHintTextColor(0xffd5c9e8);reply.setTextSize(12);reply.setHint(I18n.t("Trả lời…"));reply.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);reply.setSingleLine(true);reply.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(500)});reply.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEND);reply.setOnEditorActionListener((v,id,e)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_SEND){sendReply();return true;}return false;});composer.addView(reply,new LinearLayout.LayoutParams(0,dp(48),1));composer.addView(icon("send","Gửi",this::sendReply),new LinearLayout.LayoutParams(dp(44),dp(44)));composer.addView(icon("x","Đóng bàn phím",this::closeReply),new LinearLayout.LayoutParams(dp(40),dp(44)));panel.addView(composer);expandedWidth=Math.min(dp(224),context.getResources().getDisplayMetrics().widthPixels-dp(16));at=new WindowManager.LayoutParams(expandedWidth,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);at.gravity=Gravity.TOP|Gravity.START;at.x=dp(8);at.y=dp(96);at.alpha=.78f;
  grip.setOnTouchListener(new View.OnTouchListener(){float x,y;int px,py;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getActionMasked()==0){x=e.getRawX();y=e.getRawY();px=at.x;py=at.y;return true;}if(e.getActionMasked()==2){at.x=px+Math.round(e.getRawX()-x);at.y=py+Math.round(e.getRawY()-y);clamp();update();return true;}return true;}});windows.addView(panel,at);render();return true;}catch(Exception e){hide();return false;}}
 private void clamp(){android.util.DisplayMetrics dm=context.getResources().getDisplayMetrics();at.x=Math.max(0,Math.min(at.x,Math.max(0,dm.widthPixels-at.width)));at.y=Math.max(dp(24),Math.min(at.y,Math.max(dp(24),dm.heightPixels-Math.max(dp(48),panel.getHeight())-dp(24))));}
 private void update(){if(panel!=null&&panel.isAttachedToWindow())try{windows.updateViewLayout(panel,at);}catch(Exception ignored){}}
 void comment(String name,String message){String line=name+": "+message;if(line.length()>320)line=line.substring(0,320);comments.addLast(line);while(comments.size()>4)comments.removeFirst();render();}
 void flags(boolean pause,boolean mute){paused=pause;muted=mute;render();}
 void viewers(int value){viewers=Math.max(0,value);if(viewerCount!=null){viewerCount.setText(viewers>=10000?String.format(java.util.Locale.US,"%.1fk",viewers/1000f):String.valueOf(viewers));viewerCount.setContentDescription(I18n.t("Người đang xem")+": "+viewers);}}
 private void render(){if(panel==null||body==null)return;body.setVisibility(collapsed?View.GONE:View.VISIBLE);tools.setVisibility(collapsed?View.GONE:View.VISIBLE);at.width=collapsed?dp(140):expandedWidth;body.removeAllViews();if(comments.isEmpty()){TextView hint=text(I18n.t("Chờ bình luận…"),11);hint.setTextColor(0xffd5c9e8);body.addView(hint);}for(String line:comments){TextView t=text(line,11);t.setMaxLines(2);t.setEllipsize(android.text.TextUtils.TruncateAt.END);t.setPadding(0,dp(3),0,dp(3));t.setOnClickListener(v->{int colon=line.indexOf(":");openReply(colon>0?"@"+line.substring(0,colon)+" ":"");});body.addView(t,new LinearLayout.LayoutParams(-1,-2));}tools.removeAllViews();tools.addView(icon("mic",muted?"Bật mic":"Tắt mic",actions::mic),new LinearLayout.LayoutParams(0,dp(44),1));tools.addView(icon(paused?"play":"pause",paused?"Tiếp tục chia sẻ":"Tạm che màn hình",actions::pause),new LinearLayout.LayoutParams(0,dp(44),1));tools.addView(icon("message_square","Trả lời bình luận",()->openReply("")),new LinearLayout.LayoutParams(0,dp(44),1));tools.addView(icon("radio","Về phòng Live",actions::room),new LinearLayout.LayoutParams(0,dp(44),1));clamp();update();}
 void openReply(String prefix){if(panel==null)return;collapsed=false;composer.setVisibility(View.VISIBLE);at.flags&=~WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;at.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE;try{windows.removeViewImmediate(panel);windows.addView(panel,at);}catch(Exception ignored){}render();reply.setText(prefix);reply.setSelection(reply.length());reply.requestFocus();reply.postDelayed(()->{if(reply!=null&&reply.hasWindowFocus())((android.view.inputmethod.InputMethodManager)context.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(reply,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);},300);}
 void closeReply(){if(reply==null||at==null)return;((android.view.inputmethod.InputMethodManager)context.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(reply.getWindowToken(),0);reply.clearFocus();composer.setVisibility(View.GONE);at.flags|=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE;update();}
 private void sendReply(){if(reply==null)return;String message=reply.getText().toString().trim();if(message.isEmpty()||SystemClock.elapsedRealtime()-lastReply<1000)return;lastReply=SystemClock.elapsedRealtime();actions.reply(message);reply.setText("");closeReply();}
 void hide(){closeReply();if(panel!=null)try{windows.removeView(panel);}catch(Exception ignored){}panel=null;body=null;tools=null;viewerCount=null;reply=null;composer=null;}
 void clear(){hide();comments.clear();}
}
